-- =============================================================================
-- WildDex database schema (Supabase / Postgres 15+)
--
-- Run once on a fresh Supabase project (SQL editor, or as the first migration).
-- Then load the species data with db/seed.sql (generated by scripts/build-data.mjs).
--
-- Layout
--   1. Reference data   groups, regions, species, species_regions   (curated by us)
--   2. User data        profiles, user_dex_*, entries, entry_photos (owned by users)
--   3. Functions        the only way the app creates/deletes entries and photos
--   4. View             my_dex: the dex screen as a single query
--   5. Security         grants, row-level security, photo storage
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. Reference data
-- -----------------------------------------------------------------------------

-- ORDER MATTERS: common < uncommon < rare < legendary. The my_dex view averages
-- tiers by their position in this list.
create type public.rarity_tier as enum ('common', 'uncommon', 'rare', 'legendary');

create table public.groups (
  id               smallint generated always as identity primary key,
  slug             text not null unique,
  name             text not null,
  sort_order       smallint not null default 0,
  default_selected boolean not null default true      -- ticked by default in the wizard
);

create table public.regions (
  id         smallint generated always as identity primary key,
  slug       text not null unique,
  name       text not null,
  sort_order smallint not null default 0
);

create table public.species (
  id              integer generated always as identity primary key,
  slug            text not null unique,                -- stable key; the seed upserts on this
  common_name     text not null,
  scientific_name text not null unique,
  group_id        smallint not null references public.groups (id),
  summary         text not null,
  habitat         text,
  best_time       text,
  is_active       boolean not null default true,
  created_at      timestamptz not null default now()
);
create index species_group_id_idx on public.species (group_id);

-- Where a species occurs, and how hard it is to find there. A row means "present".
-- Rarity lives here (per nation) so that "rare in England, common in Scotland" is
-- representable. Adding a region later means adding rows, not changing this table.
create table public.species_regions (
  species_id integer  not null references public.species (id) on delete cascade,
  region_id  smallint not null references public.regions (id),
  rarity     public.rarity_tier not null,
  primary key (species_id, region_id)
);
create index species_regions_region_id_idx on public.species_regions (region_id);


-- -----------------------------------------------------------------------------
-- 2. User data
-- -----------------------------------------------------------------------------

-- A profile row exists once a user has finished the wizard, so "has a dex" is
-- simply "has a profile". Created by save_dex_settings(), NOT by a trigger on
-- auth.users (triggers that fail inside auth sign-up fail silently and are
-- painful to debug).
create table public.profiles (
  id         uuid primary key references auth.users (id) on delete cascade,
  dex_name   text check (char_length(dex_name) between 1 and 40),
  created_at timestamptz not null default now()
);

-- The wizard choices. Changing these only changes what the dex VIEW shows;
-- entries are never touched.
create table public.user_dex_groups (
  user_id  uuid     not null references public.profiles (id) on delete cascade,
  group_id smallint not null references public.groups (id),
  primary key (user_id, group_id)
);
create index user_dex_groups_group_id_idx on public.user_dex_groups (group_id);

create table public.user_dex_regions (
  user_id   uuid     not null references public.profiles (id) on delete cascade,
  region_id smallint not null references public.regions (id),
  primary key (user_id, region_id)
);
create index user_dex_regions_region_id_idx on public.user_dex_regions (region_id);

-- One entry per user per species: "this user has found this species".
-- Entries hang off the species, not off the dex settings.
create table public.entries (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid    not null references public.profiles (id) on delete cascade,
  species_id    integer not null references public.species (id),
  first_seen_on date    not null default current_date,
  location_text text check (char_length(location_text) <= 200),
  notes         text check (char_length(notes) <= 2000),
  created_at    timestamptz not null default now(),
  unique (user_id, species_id),
  unique (id, user_id)            -- lets entry_photos prove photo owner = entry owner
);
create index entries_species_id_idx on public.entries (species_id);

-- Every entry has at least one photo (enforced by the functions below).
-- Two files per photo: a ~2000px display image and a ~400px thumbnail, both
-- produced in the browser before upload, so the dex grid never loads big images.
create table public.entry_photos (
  id           uuid primary key default gen_random_uuid(),
  entry_id     uuid not null,
  user_id      uuid not null,
  storage_path text not null unique,   -- '<user_id>/<photo uuid>.jpg'
  thumb_path   text not null unique,   -- '<user_id>/<photo uuid>-thumb.jpg'
  is_cover     boolean not null default false,
  created_at   timestamptz not null default now(),
  foreign key (entry_id, user_id) references public.entries (id, user_id) on delete cascade
);
create index entry_photos_entry_user_idx on public.entry_photos (entry_id, user_id);
-- At most one cover photo per entry, enforced by the database.
create unique index entry_photos_one_cover_per_entry on public.entry_photos (entry_id) where is_cover;


-- -----------------------------------------------------------------------------
-- 3. Functions
--
-- The app reads tables directly but changes entries and photos ONLY through these,
-- so rules like "an entry always has a photo" and "exactly one cover" can't be
-- broken by a buggy client. They are SECURITY DEFINER (run with elevated rights)
-- so they can write tables the client has no write access to; each one therefore
-- checks auth.uid() itself and pins search_path to '' (a standard safety rule for
-- definer functions: every object is schema-qualified).
-- -----------------------------------------------------------------------------

-- Wizard final step, and "edit my dex" later. Creates the profile if needed and
-- replaces the group/region selections. Runs with the CALLER's rights, so the
-- row-level security policies below apply to it.
create function public.save_dex_settings(
  p_dex_name   text,
  p_group_ids  smallint[],
  p_region_ids smallint[]
) returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null then
    raise exception 'not signed in' using errcode = '28000';
  end if;
  if coalesce(array_length(p_group_ids, 1), 0) = 0 then
    raise exception 'choose at least one species group' using errcode = '22023';
  end if;
  if coalesce(array_length(p_region_ids, 1), 0) = 0 then
    raise exception 'choose at least one region' using errcode = '22023';
  end if;

  insert into public.profiles (id, dex_name)
  values (v_uid, nullif(btrim(p_dex_name), ''))
  on conflict (id) do update set dex_name = excluded.dex_name;

  delete from public.user_dex_groups where user_id = v_uid;
  insert into public.user_dex_groups (user_id, group_id)
  select distinct v_uid, g from unnest(p_group_ids) as g;

  delete from public.user_dex_regions where user_id = v_uid;
  insert into public.user_dex_regions (user_id, region_id)
  select distinct v_uid, r from unnest(p_region_ids) as r;
end;
$$;

-- Unlock a species: creates the entry AND its first (cover) photo atomically.
-- The browser uploads both image files to storage first, then calls this.
create function public.log_entry(
  p_species_id    integer,
  p_first_seen_on date,
  p_location_text text,
  p_notes         text,
  p_storage_path  text,
  p_thumb_path    text
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid      uuid := auth.uid();
  v_entry_id uuid;
begin
  if v_uid is null then
    raise exception 'not signed in' using errcode = '28000';
  end if;
  if not exists (select 1 from public.profiles where id = v_uid) then
    raise exception 'create your dex first' using errcode = '22023';
  end if;
  if not exists (select 1 from public.species where id = p_species_id and is_active) then
    raise exception 'unknown species' using errcode = '22023';
  end if;
  if not (starts_with(p_storage_path, v_uid::text || '/') and starts_with(p_thumb_path, v_uid::text || '/')) then
    raise exception 'photo path must be inside your own folder' using errcode = '42501';
  end if;

  insert into public.entries (user_id, species_id, first_seen_on, location_text, notes)
  values (
    v_uid,
    p_species_id,
    coalesce(p_first_seen_on, current_date),
    nullif(btrim(p_location_text), ''),
    nullif(btrim(p_notes), '')
  )
  returning id into v_entry_id;      -- a second log for the same species fails on unique (user_id, species_id)

  insert into public.entry_photos (entry_id, user_id, storage_path, thumb_path, is_cover)
  values (v_entry_id, v_uid, p_storage_path, p_thumb_path, true);

  return v_entry_id;
end;
$$;

-- Add a photo from a later sighting to an existing entry.
create function public.add_entry_photo(
  p_entry_id     uuid,
  p_storage_path text,
  p_thumb_path   text
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid      uuid := auth.uid();
  v_photo_id uuid;
begin
  if v_uid is null then
    raise exception 'not signed in' using errcode = '28000';
  end if;
  if not exists (select 1 from public.entries where id = p_entry_id and user_id = v_uid) then
    raise exception 'entry not found' using errcode = '22023';
  end if;
  if not (starts_with(p_storage_path, v_uid::text || '/') and starts_with(p_thumb_path, v_uid::text || '/')) then
    raise exception 'photo path must be inside your own folder' using errcode = '42501';
  end if;

  insert into public.entry_photos (entry_id, user_id, storage_path, thumb_path)
  values (p_entry_id, v_uid, p_storage_path, p_thumb_path)
  returning id into v_photo_id;

  return v_photo_id;
end;
$$;

-- Choose which photo is the entry's cover (the image on the dex card).
create function public.set_cover_photo(p_photo_id uuid) returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid      uuid := auth.uid();
  v_entry_id uuid;
begin
  if v_uid is null then
    raise exception 'not signed in' using errcode = '28000';
  end if;
  select entry_id into v_entry_id
  from public.entry_photos
  where id = p_photo_id and user_id = v_uid;
  if not found then
    raise exception 'photo not found' using errcode = '22023';
  end if;

  update public.entry_photos set is_cover = false where entry_id = v_entry_id and is_cover;
  update public.entry_photos set is_cover = true  where id = p_photo_id;
end;
$$;

-- Delete one photo. Rules:
--   * deleting the cover promotes the oldest remaining photo to cover
--   * deleting the LAST photo deletes the entry (the card goes back to grey)
-- Returns the two storage paths; the app then deletes those files from storage
-- (SQL can't safely delete storage files itself).
create function public.delete_entry_photo(p_photo_id uuid) returns text[]
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid   uuid := auth.uid();
  v_photo public.entry_photos;
begin
  if v_uid is null then
    raise exception 'not signed in' using errcode = '28000';
  end if;
  select * into v_photo
  from public.entry_photos
  where id = p_photo_id and user_id = v_uid;
  if not found then
    raise exception 'photo not found' using errcode = '22023';
  end if;

  delete from public.entry_photos where id = p_photo_id;

  if not exists (select 1 from public.entry_photos where entry_id = v_photo.entry_id) then
    delete from public.entries where id = v_photo.entry_id;
  elsif v_photo.is_cover then
    update public.entry_photos
    set is_cover = true
    where id = (
      select id from public.entry_photos
      where entry_id = v_photo.entry_id
      order by created_at, id
      limit 1
    );
  end if;

  return array[v_photo.storage_path, v_photo.thumb_path];
end;
$$;


-- -----------------------------------------------------------------------------
-- 4. The dex screen as one query
--
-- One row per species the current user's wizard choices include, with their entry
-- (if any) and cover photo. Entries for species outside the current selection
-- still exist; they are just not listed here.
--
-- RARITY: each nation has its own tier on species_regions. For the nations the
-- user selected AND the species occurs in, we average the tiers and round, with
-- halves rounding UP to the rarer tier:
--     rare (3) in England + common (1) in Scotland = 2 = uncommon
--     rare (3) + uncommon (2) = 2.5 -> rare
-- security_invoker makes the view obey the caller's row-level security.
-- -----------------------------------------------------------------------------
create view public.my_dex with (security_invoker = true) as
select
  s.id               as species_id,
  s.slug,
  s.common_name,
  s.scientific_name,
  g.slug             as group_slug,
  g.name             as group_name,
  g.sort_order       as group_sort_order,
  (enum_range(null::public.rarity_tier))[
    round(avg(array_position(enum_range(null::public.rarity_tier), sr.rarity)))::int
  ]                  as rarity,
  e.id               as entry_id,
  e.first_seen_on,
  e.location_text,
  cp.id              as cover_photo_id,
  cp.thumb_path      as cover_thumb_path,
  cp.storage_path    as cover_storage_path
from public.species s
join public.groups g            on g.id = s.group_id
join public.species_regions sr  on sr.species_id = s.id
join public.user_dex_regions udr on udr.region_id = sr.region_id and udr.user_id = (select auth.uid())
join public.user_dex_groups  udg on udg.group_id  = s.group_id  and udg.user_id = (select auth.uid())
left join public.entries e       on e.species_id = s.id and e.user_id = (select auth.uid())
left join public.entry_photos cp on cp.entry_id = e.id and cp.is_cover
where s.is_active
group by s.id, g.id, e.id, cp.id;


-- -----------------------------------------------------------------------------
-- 5. Security
--
-- Two layers, both must allow an action:
--   GRANTs  = which operations a role may attempt on a table/column at all
--   RLS     = which ROWS that role may touch
-- Supabase grants new tables to anon/authenticated by default, so we remove that
-- and grant back only what the app needs. Anything not listed is denied.
-- The seed script and migrations run as the privileged owner role and bypass this.
-- -----------------------------------------------------------------------------
revoke all on all tables    in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
alter default privileges in schema public revoke all on tables    from anon, authenticated;
alter default privileges in schema public revoke all on sequences from anon, authenticated;

-- Reference data: anyone can read, nobody can write through the API.
grant select on public.groups, public.regions, public.species, public.species_regions
  to anon, authenticated;

-- User data
grant select, insert, update on public.profiles         to authenticated;
grant select, insert, delete on public.user_dex_groups  to authenticated;
grant select, insert, delete on public.user_dex_regions to authenticated;
grant select on public.entries      to authenticated;
grant select on public.entry_photos to authenticated;
-- Entries: only these columns can be edited directly (not species_id / user_id).
grant update (first_seen_on, location_text, notes) on public.entries to authenticated;
-- Creating entries, adding/removing photos, covers: via the functions only.

grant select on public.my_dex to authenticated;

-- Functions are executable by everyone by default; restrict to signed-in users.
revoke execute on function public.save_dex_settings(text, smallint[], smallint[])                       from public, anon, authenticated;
revoke execute on function public.log_entry(integer, date, text, text, text, text)                      from public, anon, authenticated;
revoke execute on function public.add_entry_photo(uuid, text, text)                                     from public, anon, authenticated;
revoke execute on function public.set_cover_photo(uuid)                                                 from public, anon, authenticated;
revoke execute on function public.delete_entry_photo(uuid)                                              from public, anon, authenticated;
grant  execute on function public.save_dex_settings(text, smallint[], smallint[])                       to authenticated;
grant  execute on function public.log_entry(integer, date, text, text, text, text)                      to authenticated;
grant  execute on function public.add_entry_photo(uuid, text, text)                                     to authenticated;
grant  execute on function public.set_cover_photo(uuid)                                                 to authenticated;
grant  execute on function public.delete_entry_photo(uuid)                                              to authenticated;

-- Row-level security: switch it on everywhere, then add policies.
-- (RLS on + no policy = no access, which is the safe default.)
alter table public.groups           enable row level security;
alter table public.regions          enable row level security;
alter table public.species          enable row level security;
alter table public.species_regions  enable row level security;
alter table public.profiles         enable row level security;
alter table public.user_dex_groups  enable row level security;
alter table public.user_dex_regions enable row level security;
alter table public.entries          enable row level security;
alter table public.entry_photos     enable row level security;

create policy "reference data is public" on public.groups          for select to anon, authenticated using (true);
create policy "reference data is public" on public.regions         for select to anon, authenticated using (true);
create policy "reference data is public" on public.species         for select to anon, authenticated using (true);
create policy "reference data is public" on public.species_regions for select to anon, authenticated using (true);

-- '(select auth.uid())' (rather than bare auth.uid()) lets Postgres evaluate the
-- id once per query instead of once per row.
create policy "own profile: read"   on public.profiles for select to authenticated using (id = (select auth.uid()));
create policy "own profile: create" on public.profiles for insert to authenticated with check (id = (select auth.uid()));
create policy "own profile: edit"   on public.profiles for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));

create policy "own dex groups"  on public.user_dex_groups  for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "own dex regions" on public.user_dex_regions for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

create policy "own entries: read" on public.entries for select to authenticated using (user_id = (select auth.uid()));
create policy "own entries: edit" on public.entries for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

create policy "own photos: read" on public.entry_photos for select to authenticated using (user_id = (select auth.uid()));


-- -----------------------------------------------------------------------------
-- Photo storage
--
-- Private bucket: files are only readable by their owner (the app requests
-- short-lived signed URLs). Files live under '<user_id>/...', and the policies
-- check that first folder against the signed-in user. When we add sharing we will
-- loosen the read policy; nothing else changes.
-- The size cap applies to the resized files the browser uploads (a few hundred KB),
-- not to the photo the user picks from their camera roll. A 10 MB original is fine.
-- -----------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('entry-photos', 'entry-photos', false, 10485760, array['image/jpeg', 'image/webp'])
on conflict (id) do nothing;

create policy "own photo files: read" on storage.objects for select to authenticated
  using (bucket_id = 'entry-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "own photo files: upload" on storage.objects for insert to authenticated
  with check (bucket_id = 'entry-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "own photo files: delete" on storage.objects for delete to authenticated
  using (bucket_id = 'entry-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
